/**
 * Extras to tick: a fieldset named by its legend, one checkbox per option with its note and price. Static
 * markup.
 */
import { For, type JSX } from "solid-js";
import { Checkbox, Fieldset, Inline, Label, Legend } from "../compose";
import { fmtMoney, tpl } from "../utils";
import type { DishOption } from "./option-chips.types";

export type SideChecksProps = {
  name: string;
  legend: string;
  options: DishOption[];
};

export function SideChecks({ name, legend, options }: SideChecksProps) {
  return (
    <Fieldset class="flex flex-col gap-2" data-slot="sides">
      <Legend size="sm" class="mb-2">
        {legend}
      </Legend>
      <For each={options ?? []}>{(o) => (
        <Label
          class={"flex items-center justify-between gap-4 rounded px-4 py-2 text-sm inset-ring inset-ring-border has-checked:bg-muted"}
          data-slot="dish-option"
        >
          <Inline class="flex items-center gap-2">
            <Checkbox name={tpl("{0}-{1}", name, o.id)} value="on" />
            <Inline>
              {o.name}
            </Inline>
          </Inline>
          <Inline class="text-muted-foreground">
            {tpl("{0} · {1}", o.note, fmtMoney(o.price, o.currency))}
          </Inline>
        </Label>
      )}</For>
    </Fieldset>
  );
}
